1	import { useNavigate } from "@tanstack/react-router";
2	import { ArrowLeft, Bot } from "lucide-react";
3	import { useCallback, useMemo, useState } from "react";
4	import {
5		type BehaviorTriggersDraft,
6		BehaviorTriggersEditor,
7	} from "@/components/agents/behaviors/behavior-triggers-editor";
8	import { CreateBehaviorForm } from "@/components/entity-tabs/behaviors-tab/create-behavior-form";
9	import { Button } from "@/components/ui/button";
10	import { Skeleton } from "@/components/ui/skeleton";
11	import { useCurrentOrg } from "@/hooks/use-current-org";
12	import { useConnections } from "@/lib/api/connections";
13	import type { PrefilledChannel } from "@/lib/behaviors/prefilled-channel";
14	
15	function nativeChannelId(channelKey: string): string {
16		return channelKey.includes(":")
17			? channelKey.slice(channelKey.indexOf(":") + 1)
18			: channelKey;
19	}
20	
21	export function BehaviorDraftEditor({
22		prefillAgentId,
23		onCancel,
24		initialTriggers,
25	}: {
26		/** Optional executor prefill; absent = the form's unlocked agent picker. */
27		prefillAgentId?: string;
28		onCancel: () => void;
29		/** Prefill one or more activation contracts (e.g. chat-link deep link). */
30		initialTriggers?: Array<Record<string, unknown>>;
31	}) {
32		const { org } = useCurrentOrg();
33		const [triggersDraft, setTriggersDraft] = useState<BehaviorTriggersDraft>({
34			ready: false,
35			triggers: [],
36		});
37		const handleTriggersChange = useCallback((draft: BehaviorTriggersDraft) => {
38			setTriggersDraft((prev) =>
39				JSON.stringify(prev) === JSON.stringify(draft) ? prev : draft,
40			);
41		}, []);
42	
43		return (
44			<CreateBehaviorForm
45				organizationId={org?.id ?? ""}
46				prefillAgentId={prefillAgentId}
47				initialMode="scratch"
48				onClose={onCancel}
49				onSuccess={onCancel}
50				hideHeader
51				hideCancel
52				submitLabel="Create Behavior"
53				submitDisabled={!triggersDraft.ready}
54				createFields={{
55					triggers: triggersDraft.triggers,
56				}}
57				triggerFields={
58					<BehaviorTriggersEditor
59						key={JSON.stringify(initialTriggers ?? "new")}
60						organizationId={org?.id ?? null}
61						initialTriggers={initialTriggers}
62						onChange={handleTriggersChange}
63					/>
64				}
65			/>
66		);
67	}
68	
69	/**
70	 * Top-level Behavior create — the only Behavior authoring entry point. The
71	 * agent is one executor choice among several (the form's agent/device
72	 * pickers), so this page takes an OPTIONAL agent prefill instead of living
73	 * under an agent. Channel/resource deep links prefill a first trigger.
74	 */
75	export function BehaviorsNewPage({
76		owner,
77		prefilled,
78	}: {
79		owner: string;
80		prefilled?: PrefilledChannel;
81	}) {
82		const navigate = useNavigate();
83		const { org } = useCurrentOrg();
84	
85		const connectionsQuery = useConnections(org?.id ?? null, {
86			status: "active",
87			limit: 500,
88		});
89		const hasPrefill = Boolean(
90			prefilled?.platform && (prefilled.listen || prefilled.resource),
91		);
92		const initialTriggers = useMemo(() => {
93			if (!prefilled?.platform || (!prefilled.listen && !prefilled.resource)) {
94				return undefined;
95			}
96			const connections = connectionsQuery.data ?? [];
97			const connection = prefilled.connection
98				? connections.find(
99						(candidate) => String(candidate.id) === prefilled.connection,
100					)
101				: (() => {
102						const candidates = connections.filter((candidate) => {
103							if (candidate.connector_key !== prefilled.platform) return false;
104							if (prefilled.resource) return true;
105							return (
106								candidate.facets.chat &&
107								(candidate.external_tenant_id ?? "") === (prefilled.team ?? "")
108							);
109						});
110						return candidates.length === 1 ? candidates[0] : undefined;
111					})();
112			const eventTypes =
113				prefilled.events
114					?.split(",")
115					.map((event) => event.trim())
116					.filter(Boolean) ?? [];
117			return [
118				{
119					kind: "event",
120					connector_key: prefilled.platform,
121					...(connection ? { connection_id: connection.id } : {}),
122					event_types:
123						eventTypes.length > 0
124							? eventTypes
125							: prefilled.listen
126								? ["message.created"]
127								: [],
128					match: prefilled.resource
129						? {
130								resource_ref: prefilled.resource,
131								...(prefilled.resource_type
132									? { resource_type: prefilled.resource_type }
133									: {}),
134							}
135						: { channel_id: nativeChannelId(prefilled.listen ?? "") },
136					execution: "turn",
137					active_run: prefilled.listen ? "steer" : "queue",
138					output: prefilled.listen ? "reply_to_source" : "silent",
139					skip_if_unchanged: !prefilled.listen,
140				},
141			];
142		}, [connectionsQuery.data, prefilled]);
143	
144		const backToBehaviors = () =>
145			void navigate({ to: "/$owner/behaviors", params: { owner } });
146	
147		const subtitle = initialTriggers
148			? prefilled?.resource
149				? `React to changes on ${prefilled.label ?? prefilled.resource}.`
150				: `React to messages in ${prefilled?.label ?? prefilled?.listen}.`
151			: hasPrefill && !connectionsQuery.isLoading
152				? "Choose the matching connection and event, then define the reaction."
153				: "Choose when the behavior runs — add more triggers if several sources should share the same reaction.";
154	
155		return (
156			<div className="flex flex-1 flex-col gap-6 px-4 py-6 lg:px-6">
157				<div className="mx-auto flex w-full min-w-0 max-w-3xl flex-col gap-4">
158					<div className="flex flex-wrap items-center justify-between gap-3">
159						<div className="flex min-w-0 items-center gap-2">
160							<Button
161								type="button"
162								variant="ghost"
163								size="sm"
164								className="h-8 gap-1.5 text-muted-foreground hover:text-foreground"
165								onClick={backToBehaviors}
166							>
167								<ArrowLeft className="h-3.5 w-3.5" />
168								Behaviors
169							</Button>
170							<h1 className="flex min-w-0 items-center gap-2 truncate font-display text-xl font-semibold">
171								<Bot className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
172								New behavior
173							</h1>
174						</div>
175					</div>
176					<p className="text-sm text-muted-foreground">{subtitle}</p>
177					{hasPrefill && connectionsQuery.isLoading ? (
178						<div className="space-y-3">
179							<Skeleton className="h-10 w-full" />
180							<Skeleton className="h-32 w-full" />
181						</div>
182					) : (
183						<BehaviorDraftEditor
184							prefillAgentId={prefilled?.agent}
185							onCancel={backToBehaviors}
186							initialTriggers={initialTriggers}
187						/>
188					)}
189				</div>
190			</div>
191		);
192	}
