1	import { Copy, LayoutTemplate, Plus } from "lucide-react";
2	import { type ReactNode, useMemo, useState } from "react";
3	import {
4		CatalogPicker,
5		type CatalogPickerItem,
6		CatalogPickerSkeleton,
7	} from "@/components/agents/catalog-picker";
8	import { TabLoadingState } from "@/components/entity-tabs/tab-states";
9	import { FormFooter } from "@/components/ui/form-footer";
10	import {
11		type BehaviorCatalogTemplate,
12		useBehaviorCatalog,
13		useCreateBehavior,
14		useCreateBehaviorVersion,
15		useSetReactionScript,
16		useUpdateBehavior,
17		useBehaviorsList,
18	} from "@/hooks/use-behaviors";
19	import { cn } from "@/lib/utils";
20	import { FromScratchPanel, type BehaviorFormDraft } from "./from-scratch-panel";
21	
22	type CreationMode = "template" | "scratch" | "clone";
23	
24	interface EditingBehavior {
25		behavior_id: string;
26		entity_id?: number;
27		name?: string;
28		slug?: string;
29		description?: string;
30		prompt?: string;
31		sources?: Array<{ name: string; query: string }>;
32		triggers?: Array<Record<string, unknown>>;
33		reaction_script?: string;
34		agent_id?: string | null;
35		agent_kind?: string | null;
36		device_worker_id?: string | null;
37		classifiers?: unknown[];
38		keying_config?: Record<string, unknown>;
39		reactions_guidance?: string;
40		model_config?: Record<string, unknown>;
41		execution_config?: Record<string, unknown>;
42		tags?: string[];
43	}
44	
45	interface CreateBehaviorFormProps {
46		onClose: () => void;
47		/** Hide the Cancel button — e.g. when this IS the empty state (nothing to cancel to). */
48		hideCancel?: boolean;
49		/** Drop the form's own title/subtitle — the host page already owns the header
50		 *  (e.g. the agent-scoped create route). Cancel lives in FormFooter only. */
51		hideHeader?: boolean;
52		organizationId: string;
53		entityId?: number;
54		entityName?: string;
55		/** Pre-fill the agent_id field when creating from an agent-scoped Behaviors tab. */
56		prefillAgentId?: string;
57		onSuccess?: (behaviorId: string) => void;
58		editingBehavior?: EditingBehavior;
59		/** Opens directly in clone flow (create catalog). */
60		initialMode?: CreationMode;
61		/** Prefill the scratch form from a catalog Behavior template. */
62		catalogPrefill?: {
63			name?: string;
64			slug?: string;
65			description?: string;
66			prompt?: string;
67			triggers?: Array<Record<string, unknown>>;
68			sources?: Array<{ name: string; query: string }>;
69			classifiers?: unknown[];
70			keying_config?: Record<string, unknown>;
71			reactions_guidance?: string;
72			reaction_script?: string;
73			model_config?: Record<string, unknown>;
74			execution_config?: Record<string, unknown>;
75			tags?: string[];
76			agent_id?: string;
77		};
78		/** UI-first Behavior composition: collect the complete definition and let
79		 * the host submit it atomically. */
80		onDraft?: (draft: BehaviorFormDraft) => void | Promise<void>;
81		triggerFields?: ReactNode;
82		submitLabel?: string;
83		submitDisabled?: boolean;
84		/** Canonical fields composed by the host (for example Behavior triggers). */
85		createFields?: { triggers?: Array<Record<string, unknown>> };
86	}
87	
88	type CatalogPrefill = NonNullable<CreateBehaviorFormProps["catalogPrefill"]>;
89	
90	function templateToPrefill(template: BehaviorCatalogTemplate): CatalogPrefill {
91		const detail = template.detail ?? {};
92		return {
93			name: template.name,
94			slug: detail.slug,
95			description: detail.description ?? template.description ?? undefined,
96			prompt: detail.prompt,
97			triggers: detail.triggers,
98			sources: detail.sources,
99			classifiers: detail.classifiers,
100			keying_config: detail.keying_config,
101			reactions_guidance: detail.reactions_guidance,
102			reaction_script: detail.reaction_script,
103			model_config: detail.model_config,
104			execution_config: detail.execution_config,
105			tags: detail.tags,
106		};
107	}
108	
109	export function CreateBehaviorForm({
110		onClose,
111		hideCancel = false,
112		hideHeader = false,
113		organizationId,
114		entityId,
115		entityName,
116		prefillAgentId,
117		onSuccess,
118		editingBehavior,
119		initialMode = "template",
120		catalogPrefill,
121		onDraft,
122		triggerFields,
123		submitLabel,
124		submitDisabled,
125		createFields,
126	}: CreateBehaviorFormProps) {
127		const createBehavior = useCreateBehavior();
128		const createVersion = useCreateBehaviorVersion();
129		const setReactionScript = useSetReactionScript();
130		const updateBehavior = useUpdateBehavior();
131		const isEditing = !!editingBehavior;
132		const [mode, setMode] = useState<CreationMode>(initialMode);
133		const [clonePrefill, setClonePrefill] = useState<
134			| {
135					name?: string;
136					slug?: string;
137					prompt?: string;
138					classifiers?: unknown[];
139					keying_config?: Record<string, unknown>;
140			  }
141			| undefined
142		>(undefined);
143		// A template picked from the "From templates" tab, folded into the scratch form.
144		const [templatePrefill, setTemplatePrefill] = useState<
145			CatalogPrefill | undefined
146		>(undefined);
147	
148		const { data: templates = [], isLoading: templatesLoading } =
149			useBehaviorCatalog();
150		const [templateSearch, setTemplateSearch] = useState("");
151		const agentPrefill = useMemo(
152			() => (prefillAgentId ? { agent_id: prefillAgentId } : undefined),
153			[prefillAgentId],
154		);
155		const templateItems = useMemo(
156			() =>
157				templates.map((t) => ({
158					key: t.id,
159					name: t.name,
160					description: t.description ?? "",
161					badges: t.detail?.tags ?? [],
162				})),
163			[templates],
164		);
165		const filteredTemplates = useMemo(
166			() =>
167				templateItems.filter(
168					(item) =>
169						item.name.toLowerCase().includes(templateSearch.toLowerCase()) ||
170						item.description.toLowerCase().includes(templateSearch.toLowerCase()),
171				),
172			[templateItems, templateSearch],
173		);
174		const handleSelectTemplate = (item: CatalogPickerItem) => {
175			const template = templates.find((t) => t.id === item.key);
176			if (!template) return;
177			const prefill = templateToPrefill(template);
178			// catalogPrefill precedence folds the agent in to keep the agent-scoped
179			// create context when a template is chosen.
180			setTemplatePrefill(
181				prefillAgentId ? { ...prefill, agent_id: prefillAgentId } : prefill,
182			);
183			setMode("scratch");
184		};
185	
186		const handleClose = () => {
187			createBehavior.reset();
188			createVersion.reset();
189			setMode(initialMode);
190			setClonePrefill(undefined);
191			setTemplatePrefill(undefined);
192			onClose();
193		};
194	
195		// The triggers this save will land on, resolved with the same precedence the
196		// two submit branches below use. The form needs them before submit: they
197		// decide whether skills are required (a schedule/window Behavior runs on its
198		// compiled instructions alone, an event-turn one does not).
199		const effectiveTriggers = isEditing
200			? (createFields?.triggers ?? editingBehavior.triggers ?? [])
201			: (createFields?.triggers ??
202				templatePrefill?.triggers ??
203				catalogPrefill?.triggers ??
204				[]);
205	
206		const handleCreate = async (params: BehaviorFormDraft) => {
207			try {
208				if (onDraft) {
209					await onDraft(params);
210					return;
211				}
212				if (isEditing) {
213					const triggers =
214						createFields?.triggers ?? editingBehavior.triggers ?? [];
215					// Single atomic create_version call — also updates Behavior-level fields.
216					await createVersion.mutateAsync({
217						behavior_id: editingBehavior.behavior_id,
218						name: params.name,
219						description: params.description,
220						prompt: params.prompt,
221						sources: params.sources,
222						set_as_current: true,
223						triggers,
224						classifiers: params.classifiers,
225						keying_config: params.keying_config,
226						reactions_guidance: params.reactions_guidance,
227						change_notes: params.change_notes,
228					});
229					// Reaction script is compiled server-side, so it's a separate call
230					const originalScript = editingBehavior.reaction_script ?? "";
231					const newScript = params.reaction_script ?? "";
232					if (newScript !== originalScript) {
233						await setReactionScript.mutateAsync({
234							behavior_id: editingBehavior.behavior_id,
235							reaction_script: newScript,
236						});
237					}
238					// Behavior-level fields (not part of version).
239					const behaviorUpdates: Record<string, unknown> = {};
240					if (params.model_config !== undefined)
241						behaviorUpdates.model_config = params.model_config;
242					if (params.execution_config !== undefined)
243						behaviorUpdates.execution_config = params.execution_config;
244					if (params.tags !== undefined) behaviorUpdates.tags = params.tags;
245					if (params.agent_id !== undefined)
246						behaviorUpdates.agent_id = params.agent_id || null;
247					if (params.agent_kind !== undefined)
248						behaviorUpdates.agent_kind = params.agent_kind || null;
249					// device_worker_id is a Behavior-level column, so it must ride the
250					// `updateBehavior` PATCH — create_version ignores it (it only writes
251					// schedule/triggers/sources). Routing it there is what makes the
252					// device pin editable at all; without it the edit silently drops the
253					// change. Sent every time so switching back to agent clears the pin
254					// (the panel emits null in that case).
255					if (params.device_worker_id !== undefined)
256						behaviorUpdates.device_worker_id = params.device_worker_id || null;
257					if (Object.keys(behaviorUpdates).length > 0) {
258						await updateBehavior.mutateAsync({
259							behavior_id: editingBehavior.behavior_id,
260							...behaviorUpdates,
261						});
262					}
263					handleClose();
264					onSuccess?.(editingBehavior.behavior_id);
265				} else {
266					const initialTriggers =
267						createFields?.triggers ??
268						templatePrefill?.triggers ??
269						catalogPrefill?.triggers ??
270						[];
271					const result = await createBehavior.mutateAsync({
272						...params,
273						// Create takes plain strings; the panel's explicit nulls (used to
274						// clear executors on edit) mean "absent" here.
275						agent_id: params.agent_id ?? undefined,
276						device_worker_id: params.device_worker_id ?? undefined,
277						agent_kind: params.agent_kind ?? undefined,
278						triggers: initialTriggers,
279					});
280					handleClose();
281					if (result.behavior_id) {
282						onSuccess?.(result.behavior_id);
283					}
284				}
285			} catch {
286				// error is shown by the panel
287			}
288		};
289	
290		const mutationState = isEditing ? createVersion : createBehavior;
291		let description = "Add a behavior";
292		if (isEditing) {
293			description = "Edit behavior configuration (saves as a new version)";
294		} else if (entityName) {
295			description = `Add a behavior for ${entityName}`;
296		}
297	
298		const editPrefill = editingBehavior
299			? {
300					entity_id: editingBehavior.entity_id,
301					name: editingBehavior.name,
302					slug: editingBehavior.slug,
303					description: editingBehavior.description,
304					prompt: editingBehavior.prompt,
305					sources: editingBehavior.sources,
306					reaction_script: editingBehavior.reaction_script,
307					device_worker_id: editingBehavior.device_worker_id ?? undefined,
308					agent_kind: editingBehavior.agent_kind ?? undefined,
309					classifiers: editingBehavior.classifiers,
310					keying_config: editingBehavior.keying_config,
311					reactions_guidance: editingBehavior.reactions_guidance,
312					model_config: editingBehavior.model_config,
313					execution_config: editingBehavior.execution_config,
314					tags: editingBehavior.tags,
315					agent_id: editingBehavior.agent_id ?? undefined,
316				}
317			: undefined;
318	
319		const titleText = isEditing ? "Edit Behavior" : "Create Behavior";
320	
321		const header = (
322			<div className="space-y-1.5">
323				<h1 className="text-2xl font-semibold leading-tight">{titleText}</h1>
324				<p className="text-sm text-muted-foreground">{description}</p>
325			</div>
326		);
327	
328		const body = (
329			<div className="py-6 space-y-6">
330				{!isEditing && (
331					<div className="flex justify-center gap-2">
332						<ModeButton
333							active={mode === "template"}
334							onClick={() => setMode("template")}
335							icon={<LayoutTemplate className="h-4 w-4" />}
336							label="From templates"
337						/>
338						<ModeButton
339							active={mode === "scratch"}
340							onClick={() => {
341								setMode("scratch");
342								setClonePrefill(undefined);
343								setTemplatePrefill(undefined);
344							}}
345							icon={<Plus className="h-4 w-4" />}
346							label="From scratch"
347						/>
348						<ModeButton
349							active={mode === "clone"}
350							onClick={() => setMode("clone")}
351							icon={<Copy className="h-4 w-4" />}
352							label="Clone existing"
353						/>
354					</div>
355				)}
356	
357				{!isEditing && mode === "template" ? (
358					<>
359						{templatesLoading ? (
360							<CatalogPickerSkeleton />
361						) : (
362							<CatalogPicker
363								items={filteredTemplates}
364								searchQuery={templateSearch}
365								onSearchChange={setTemplateSearch}
366								onSelect={handleSelectTemplate}
367								searchPlaceholder="Search templates..."
368								searchAriaLabel="Search behavior templates"
369								emptyMessage={
370									templateItems.length === 0
371										? "No behavior templates available."
372										: undefined
373								}
374							/>
375						)}
376						{hideHeader && !hideCancel ? (
377							<FormFooter onCancel={handleClose} />
378						) : null}
379					</>
380				) : !isEditing && mode === "clone" && !clonePrefill ? (
381					<>
382						<CloneBehaviorPicker
383							organizationId={organizationId}
384							onSelect={(prefill) => {
385								setClonePrefill(prefill);
386								setMode("scratch");
387							}}
388						/>
389						{hideHeader && !hideCancel ? (
390							<FormFooter onCancel={handleClose} />
391						) : null}
392					</>
393				) : (
394					<FromScratchPanel
395						organizationId={organizationId}
396						entityId={entityId}
397						prefill={
398							editPrefill ??
399							clonePrefill ??
400							templatePrefill ??
401							catalogPrefill ??
402							agentPrefill
403						}
404						onSubmit={handleCreate}
405						isSubmitting={mutationState.isPending}
406						error={
407							mutationState.error ? (mutationState.error as Error).message : null
408						}
409						isEditing={isEditing}
410						onCancel={hideCancel ? undefined : handleClose}
411						triggerFields={triggerFields}
412						submitLabel={submitLabel}
413						submitDisabled={submitDisabled}
414						triggers={effectiveTriggers}
415					/>
416				)}
417			</div>
418		);
419	
420		return (
421			<div className="flex flex-col">
422				{hideHeader ? null : header}
423				{body}
424			</div>
425		);
426	}
427	
428	function ModeButton({
429		active,
430		onClick,
431		icon,
432		label,
433	}: {
434		active: boolean;
435		onClick: () => void;
436		icon: React.ReactNode;
437		label: string;
438	}) {
439		return (
440			<button
441				type="button"
442				onClick={onClick}
443				className={cn(
444					"flex items-center gap-2 rounded-md border px-3 py-2 text-sm transition-colors",
445					active
446						? "border-primary bg-primary/5 text-primary"
447						: "border-border text-muted-foreground hover:border-muted-foreground/30 hover:text-foreground",
448				)}
449			>
450				{icon}
451				{label}
452			</button>
453		);
454	}
455	
456	function CloneBehaviorPicker({
457		organizationId,
458		onSelect,
459	}: {
460		organizationId: string;
461		onSelect: (prefill: {
462			name: string;
463			slug: string;
