30		// New form: one blank connector-event draft.
31		if (initialTriggers === undefined) {
32			return [{ key: newSlotKey(), initial: undefined }];
33		}
34		// Explicit manual Behavior.
35		if (initialTriggers.length === 0) {
36			return [{ key: newSlotKey(), initial: null }];
37		}
38		return initialTriggers.map((trigger) => ({
39			key: newSlotKey(),
40			initial: trigger,
41		}));
42	}
43	
44	function isScheduleDraft(draft: BehaviorTriggerDraft | undefined): boolean {
45		if (!draft) return false;
46		return draft.kind === "time" || draft.trigger?.kind === "schedule";
47	}
48	
49	function draftsEqual(
50		left: BehaviorTriggerDraft | undefined,
51		right: BehaviorTriggerDraft,
52	): boolean {
53		if (!left) return false;
54		return (
55			left.ready === right.ready &&
56			left.kind === right.kind &&
57			JSON.stringify(left.trigger) === JSON.stringify(right.trigger)
58		);
59	}
60	
61	function aggregateDraft(
62		slots: Slot[],
63		drafts: Record<string, BehaviorTriggerDraft>,
64	): BehaviorTriggersDraft {
65		const ordered = slots.map(
66			(slot) =>
67				drafts[slot.key] ??
68				({
69					ready: false,
70					kind: "connector_event",
71				} satisfies BehaviorTriggerDraft),
72		);
73		const multi = slots.length > 1;
74	
75		if (!multi && ordered[0]?.kind === "manual") {
76			return { ready: ordered[0].ready, triggers: [] };
77		}
78	
79		const scheduleCount = ordered.filter(isScheduleDraft).length;
80		const hasManual = ordered.some((draft) => draft.kind === "manual");
81		const ready =
82			!hasManual &&
83			scheduleCount <= 1 &&
84			ordered.length > 0 &&
85			ordered.every((draft) => draft.ready && draft.trigger);
86	
87		return {
88			ready,
89			triggers: ordered
90				.filter((draft) => draft.trigger)
91				.map((draft) => draft.trigger as Record<string, unknown>),
92		};
93	}
94	
95	/**
96	 * Multi-trigger "When" editor. Each activation is OR'd at runtime; at most one
97	 * schedule is allowed; an empty list is manual-only. Nested single-trigger
98	 * editors stay the source of truth for connector/schedule form state.
99	 */
100	export function BehaviorTriggersEditor({
101		organizationId,
102		initialTriggers,
103		onChange,
104	}: {
105		organizationId: string | null;
106		/**
107		 * `undefined` — new Behavior (one blank draft).
108		 * `[]` — manual-only.
109		 * non-empty — load every stored trigger for edit.
110		 */
111		initialTriggers?: Array<Record<string, unknown>>;
112		onChange: (draft: BehaviorTriggersDraft) => void;
113	}) {
114		const listId = useId();
115		const [slots, setSlots] = useState<Slot[]>(() =>
116			slotsFromInitial(initialTriggers),
117		);
118		const [drafts, setDrafts] = useState<Record<string, BehaviorTriggerDraft>>(
119			{},
120		);
121		const lastPublished = useRef<string>("");
122	
123		useEffect(() => {
124			const next = aggregateDraft(slots, drafts);
125			const serialized = JSON.stringify(next);
126			if (serialized === lastPublished.current) return;
127			lastPublished.current = serialized;
128			onChange(next);
129		}, [slots, drafts, onChange]);
130	
131		const scheduleOwnerKey =
132			slots.find((slot) => isScheduleDraft(drafts[slot.key]))?.key ??
133			slots.find(
134				(slot) =>
135					slot.initial &&
136					typeof slot.initial === "object" &&
137					slot.initial.kind === "schedule" &&
138					!drafts[slot.key],
139			)?.key ??
140			null;
141	
142		const handleSlotChange = useCallback(
143			(key: string, draft: BehaviorTriggerDraft) => {
144				setDrafts((prev) => {
145					if (draftsEqual(prev[key], draft)) return prev;
146					return { ...prev, [key]: draft };
147				});
148			},
149			[],
150		);
151	
152		const addTrigger = () => {
153			const only = slots[0];
154			const onlyDraft = only ? drafts[only.key] : undefined;
155			if (
156				slots.length === 1 &&
157				(onlyDraft?.kind === "manual" || only?.initial === null)
158			) {
159				const key = newSlotKey();
160				setDrafts({});
161				setSlots([{ key, initial: undefined }]);
162				return;
163			}
164			setSlots((current) => [
165				...current,
166				{ key: newSlotKey(), initial: undefined },
167			]);
168		};
169	
170		const removeSlot = (key: string) => {
171			if (slots.length <= 1) {
172				const nextKey = newSlotKey();
173				setDrafts({});
174				setSlots([{ key: nextKey, initial: null }]);
175				return;
176			}
177			setDrafts((prev) => {
178				const next = { ...prev };
179				delete next[key];
180				return next;
181			});
182			setSlots((current) => current.filter((slot) => slot.key !== key));
183		};
184	
185		return (
186			<section className="space-y-4" aria-labelledby={`${listId}-heading`}>
187				<div className="space-y-1">
188					<h2 id={`${listId}-heading`} className="text-sm font-medium">
189						When
190					</h2>
191					<p className="text-xs text-muted-foreground">
192						Each trigger can start this Behavior independently (OR). At most one
193						schedule. If several match the same event, the first listed wins for
194						run options.
195					</p>
196				</div>
197	
198				<div className="space-y-3">
199					{slots.map((slot, index) => {
200						const multi = slots.length > 1;
201						const kinds: TriggerKind[] = multi
202							? scheduleOwnerKey && scheduleOwnerKey !== slot.key
203								? ["connector_event"]
204								: ["connector_event", "time"]
205							: ["connector_event", "time", "manual"];
206						const draft = drafts[slot.key];
207						const showRemove =
208							multi || (draft ? draft.kind !== "manual" : slot.initial !== null);
209						return (
210							<div
211								key={slot.key}
212								className={cn(
213									"space-y-3 rounded-lg border bg-card/40 p-3",
214									multi && "relative",
215								)}
216							>
217								<div className="flex items-center justify-between gap-2">
218									<p className="text-xs font-medium text-muted-foreground">
219										{multi ? `Trigger ${index + 1}` : "Trigger"}
220									</p>
221									{showRemove ? (
222										<Button
223											type="button"
224											variant="ghost"
225											size="icon"
226											className="h-7 w-7 text-muted-foreground hover:text-destructive"
227											aria-label={
228												multi ? `Remove trigger ${index + 1}` : "Clear trigger"
229											}
230											onClick={() => removeSlot(slot.key)}
231										>
232											<Trash2 className="h-3.5 w-3.5" />
233										</Button>
234									) : null}
235								</div>
236								<SlotTriggerEditor
237									slotKey={slot.key}
238									organizationId={organizationId}
239									initial={slot.initial}
240									kinds={kinds}
241									fieldIdPrefix={`${listId}-${slot.key}-`}
242									onChange={handleSlotChange}
243								/>
244							</div>
245						);
246					})}
247				</div>
248	
249				<Button
250					type="button"
251					variant="outline"
252					size="sm"
253					className="w-full sm:w-auto"
254					onClick={addTrigger}
255				>
256					<Plus className="mr-1.5 h-3.5 w-3.5" />
257					Add another trigger
258				</Button>
259			</section>
260		);
261	}
262	
263	/** Stable onChange identity per slot so nested editors do not loop. */
264	function SlotTriggerEditor({
265		slotKey,
266		organizationId,
267		initial,
268		kinds,
269		fieldIdPrefix,
270		onChange,
271	}: {
272		slotKey: string;
273		organizationId: string | null;
274		initial: Record<string, unknown> | null | undefined;
275		kinds: TriggerKind[];
276		fieldIdPrefix: string;
277		onChange: (key: string, draft: BehaviorTriggerDraft) => void;
278	}) {
279		const handleChange = useCallback(
280			(draft: BehaviorTriggerDraft) => onChange(slotKey, draft),
281			[onChange, slotKey],
282		);
283		return (
284			<BehaviorTriggerEditor
285				organizationId={organizationId}
286				initialTrigger={initial}
287				allowedKinds={kinds}
288				showSectionHeader={false}
289				fieldIdPrefix={fieldIdPrefix}
290				onChange={handleChange}
291			/>
292		);
293	}
