// @vitest-environment jsdom
import { render, screen, waitFor } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

vi.mock("@tanstack/react-router", () => ({
	useNavigate: () => vi.fn(),
}));

vi.mock("@/hooks/use-current-org", () => ({
	useCurrentOrg: () => ({ org: { id: "org-1", slug: "acme" } }),
}));

vi.mock("@/lib/api/connections", () => ({
	useConnections: () => ({
		data: [
			{
				id: 17,
				connector_key: "slack",
				display_name: "Acme Slack",
				facets: { chat: true },
			},
			{
				id: 18,
				connector_key: "github",
				display_name: "Acme GitHub",
				facets: { chat: false },
			},
		],
		isLoading: false,
	}),
	useConnectorDefinitions: () => ({
		data: [
			{
				key: "slack",
				behavior_events: [
					{
						key: "message.created",
						label: "A message is sent",
						capabilities: { steering: true, replyToSource: true },
					},
				],
			},
			{
				key: "github",
				behavior_events: [
					{
						key: "pull_request.updated",
						label: "pull request · updated",
						capabilities: {},
					},
				],
			},
		],
		isLoading: false,
	}),
	useDevices: () => ({ data: [] }),
}));

vi.mock("@/lib/api/agents", () => ({
	useAgents: () => ({ data: [] }),
}));

import { BehaviorTriggersEditor } from "./behavior-triggers-editor";

const SLACK_TRIGGER = {
	kind: "event",
	connector_key: "slack",
	connection_id: 17,
	event_types: ["message.created"],
};

const GITHUB_TRIGGER = {
	kind: "event",
	connector_key: "github",
	connection_id: 18,
	event_types: ["pull_request.updated"],
};

describe("BehaviorTriggersEditor", () => {
	it("authors one trigger and offers no way to add a second", () => {
		render(<BehaviorTriggersEditor organizationId="org-1" onChange={() => {}} />);

		expect(screen.queryByRole("button", { name: /add another/i })).toBeNull();
		expect(screen.getByText("Trigger")).toBeTruthy();
		expect(screen.queryByText("Trigger 2")).toBeNull();
	});

	it("drops the ordering explainer that only applies to several triggers", () => {
		render(<BehaviorTriggersEditor organizationId="org-1" onChange={() => {}} />);

		expect(screen.queryByText(/first listed wins/i)).toBeNull();
	});

	it("keeps every trigger of a Behavior already stored with more than one", async () => {
		const onChange = vi.fn();
		render(
			<BehaviorTriggersEditor
				organizationId="org-1"
				initialTriggers={[SLACK_TRIGGER, GITHUB_TRIGGER]}
				onChange={onChange}
			/>,
		);

		// Both slots render: opening the form must not rewrite an activation the
		// author never touched.
		expect(screen.getByText("Trigger 1")).toBeTruthy();
		expect(screen.getByText("Trigger 2")).toBeTruthy();
		// Order still decides run options for these rows, so the rule stays visible.
		expect(screen.getByText(/first listed wins/i)).toBeTruthy();

		await waitFor(() => {
			const published = onChange.mock.calls.at(-1)?.[0];
			expect(published?.triggers).toHaveLength(2);
		});
	});

	it("renders a stored manual Behavior without inventing a trigger", async () => {
		const onChange = vi.fn();
		render(
			<BehaviorTriggersEditor
				organizationId="org-1"
				initialTriggers={[]}
				onChange={onChange}
			/>,
		);

		await waitFor(() => {
			const published = onChange.mock.calls.at(-1)?.[0];
			expect(published?.triggers).toHaveLength(0);
		});
	});
});

