// One trigger subscribes to many event types — the contract has always taken
// up to 32. Holding a single key here silently narrowed a stored trigger to
// one event the moment the author touched the picker.
const [eventKeys, setEventKeys] = useState<string[]>(() =>
	initialEventTypes.filter(
		(value): value is string => typeof value === "string",
	),
);

const events = definition?.behavior_events ?? [];
const selectedEvents = events.filter((event) =>
	eventKeys.includes(event.key),
);
/** Run options and the description follow the first selection. */
const selectedEvent = selectedEvents[0];
/**
 * `match` applies to every subscribed event, so the filter form is only safe
 * when all of them declare the same fields. GitHub is the live case: only
 * `pull_request.created` declares `repository`, so pairing it with
 * `commits.updated` would otherwise render a filter the second event never
 * advertised. Fail closed and offer none.
 */
const sharedFilterSchema = (() => {
	if (selectedEvents.length === 0) return undefined;
	const signature = (event: (typeof selectedEvents)[number]) =>
		JSON.stringify(
			Object.keys(
				(event.filterSchema?.properties as Record<string, unknown>) ?? {},
			).sort(),
		);
	const first = selectedEvents[0];
	if (!first?.filterSchema) return undefined;
	return selectedEvents.every((event) => signature(event) === signature(first))
		? first.filterSchema
		: undefined;
})();

