const toggleEvent = (key: string) => {
	// Keep catalog order so the "first selection" that supplies run options is
	// the one listed first, not the one clicked first.
	const next = eventKeys.includes(key)
		? eventKeys.filter((candidate) => candidate !== key)
		: events
				.map((event) => event.key)
				.filter(
					(candidate) =>
						candidate === key || eventKeys.includes(candidate),
				);
	setEventKeys(next);
	// `match` is shared by every subscribed event, so a selection change can
