	setFilter(preserveResourceMatch);
	const primary = events.find((event) => event.key === next[0]);
	const execution = primary?.defaults?.execution ?? "turn";
	const activeRun = primary?.defaults?.activeRun ?? "queue";
	const output = outputForExecution(
		execution,
		primary?.defaults?.output ?? "silent",
	);
	setExecutionMode(execution);
	setActiveRunPolicy(activeRunForDelivery(execution, output, activeRun));
	setOutputMode(output);
};

