import { BehaviorTriggerEditor } from "./behavior-trigger-editor";

function renderEditor(eventTypes: string[], onChange = vi.fn()) {
	render(
		<BehaviorTriggerEditor
			organizationId="org-1"
			initialTrigger={{
				kind: "event",
				connector_key: "github",
				connection_id: 18,
				event_types: eventTypes,
			}}
			onChange={onChange}
		/>,
	);
	return onChange;
}

const lastTrigger = (onChange: ReturnType<typeof vi.fn>) =>
	onChange.mock.calls.at(-1)?.[0]?.trigger as
		| Record<string, unknown>
		| undefined;

describe("BehaviorTriggerEditor event subscriptions", () => {
	it("subscribes one trigger to several events", async () => {
		const onChange = renderEditor(["pull_request.created"]);

		fireEvent.click(
			screen.getByRole("checkbox", { name: "pull request · updated" }),
		);

		await waitFor(() => {
			expect(lastTrigger(onChange)?.event_types).toEqual([
				"pull_request.created",
				"pull_request.updated",
			]);
		});
	});

	it("orders subscriptions by the connector catalog, not by click order", async () => {
		const onChange = renderEditor([]);

		// Clicked last-to-first; the payload must still read in catalog order,
		// because position 0 is what supplies the trigger's run options.
		fireEvent.click(
			screen.getByRole("checkbox", { name: "Repository commits change" }),
		);
		fireEvent.click(
			screen.getByRole("checkbox", { name: "A pull request is created" }),
		);

		await waitFor(() => {
			expect(lastTrigger(onChange)?.event_types).toEqual([
				"pull_request.created",
				"commits.updated",
			]);
		});
	});

	it("keeps a stored multi-event trigger instead of narrowing it to one", async () => {
		const onChange = renderEditor([
			"pull_request.created",
			"pull_request.updated",
		]);

		// Touching the picker used to collapse the whole array to the one key the
		// editor happened to be holding.
		fireEvent.click(
			screen.getByRole("checkbox", { name: "Repository commits change" }),
		);

		await waitFor(() => {
			expect(lastTrigger(onChange)?.event_types).toEqual([
				"pull_request.created",
				"pull_request.updated",
				"commits.updated",
			]);
		});
	});

	it("offers the filter an event declares", () => {
		renderEditor(["pull_request.created"]);

		expect(screen.getByText("Repository")).toBeTruthy();
	});

	it("withdraws the filter when the selection mixes events that do not share it", async () => {
		renderEditor(["pull_request.created"]);
		expect(screen.getByText("Repository")).toBeTruthy();

		// `match` applies to every subscribed event, so a filter only one of them
		// advertises must not stay on screen.
		fireEvent.click(
			screen.getByRole("checkbox", { name: "Repository commits change" }),
		);

		await waitFor(() => {
			expect(screen.queryByText("Repository")).toBeNull();
		});
	});
});

