#!/usr/bin/env python3
"""Build the self-contained UI proof page for lobu#2515 / owletto#732."""
import base64
import pathlib

HERE = pathlib.Path(__file__).parent


def img(name: str) -> str:
    raw = (HERE / name).read_bytes()
    return "data:image/png;base64," + base64.b64encode(raw).decode()


BEFORE = img("before-when-web.png")
AFTER = img("after-when-web.png")
TWO = img("before-two-triggers-web.png")

MUTATIONS = [
    (
        "Emit <code>filter</code> instead of <code>declaredMatch(filter, …)</code>",
        "Removes the narrowing entirely — the old behaviour of shipping every "
        "field the form is holding, whatever the selection declares.",
        "1",
        "narrows the emitted match to what the selection declares, without losing it",
    ),
    (
        "Drop the <code>resource_ref</code> / <code>resource_type</code> carve-out",
        "Those two are the resource-prefill contract, not connector filter fields. "
        "Narrowing them away would break prefill from a resource page.",
        "1",
        "BehaviorDraftEditor &gt; lets connector-wide resource suggestions choose an event",
    ),
    (
        "Restore <code>setFilter(preserveResourceMatch)</code> in <code>toggleEvent</code>",
        "The original bug: wipe the author's filter from state on every toggle "
        "rather than narrowing it on the way out.",
        "1",
        "narrows the emitted match to what the selection declares, without losing it",
    ),
]

rows = "\n".join(
    f"""      <tr>
        <th><span class="mut">{mut}</span><span class="why">{why}</span></th>
        <td class="num"><span class="count">{n}</span></td>
        <td class="tname">{test}</td>
      </tr>"""
    for mut, why, n, test in MUTATIONS
)

