export interface BehaviorTriggersDraft {
	ready: boolean;
	/** Canonical activation contracts; empty means manual-only. */
	triggers: Array<Record<string, unknown>>;
}

type Slot = {
	key: string;
	/** Seed for the nested editor; stable for the life of the slot. */
	initial: Record<string, unknown> | null | undefined;
};

function newSlotKey(): string {
	return crypto.randomUUID();
}

function slotsFromInitial(
	initialTriggers: Array<Record<string, unknown>> | undefined,
): Slot[] {
	// New form: one blank connector-event draft.
	if (initialTriggers === undefined) {
		return [{ key: newSlotKey(), initial: undefined }];
	}
	// Explicit manual Behavior.
	if (initialTriggers.length === 0) {
		return [{ key: newSlotKey(), initial: null }];
	}
	return initialTriggers.map((trigger) => ({
		key: newSlotKey(),
		initial: trigger,
	}));
}

function isScheduleDraft(draft: BehaviorTriggerDraft | undefined): boolean {
	if (!draft) return false;
	return draft.kind === "time" || draft.trigger?.kind === "schedule";
}

function draftsEqual(
	left: BehaviorTriggerDraft | undefined,
	right: BehaviorTriggerDraft,
): boolean {
	if (!left) return false;
	return (
		left.ready === right.ready &&
		left.kind === right.kind &&
		JSON.stringify(left.trigger) === JSON.stringify(right.trigger)
	);
}

function aggregateDraft(
	slots: Slot[],
	drafts: Record<string, BehaviorTriggerDraft>,
): BehaviorTriggersDraft {
	const ordered = slots.map(
		(slot) =>
			drafts[slot.key] ??
			({
				ready: false,
				kind: "connector_event",
			} satisfies BehaviorTriggerDraft),
	);
	const multi = slots.length > 1;

	if (!multi && ordered[0]?.kind === "manual") {
		return { ready: ordered[0].ready, triggers: [] };
	}

	const scheduleCount = ordered.filter(isScheduleDraft).length;
	const hasManual = ordered.some((draft) => draft.kind === "manual");
	const ready =
		!hasManual &&
		scheduleCount <= 1 &&
		ordered.length > 0 &&
		ordered.every((draft) => draft.ready && draft.trigger);

	return {
		ready,
		triggers: ordered
			.filter((draft) => draft.trigger)
			.map((draft) => draft.trigger as Record<string, unknown>),
	};
}

