import base64
import pathlib
import subprocess

HERE = pathlib.Path(__file__).parent


def img(name: str, width: int = 1400) -> str:
    src = HERE / name
    out = HERE / f".web-{name}"
    subprocess.run(
        ["sips", "-Z", str(width), str(src), "--out", str(out)],
        check=True,
        capture_output=True,
    )
    return "data:image/png;base64," + base64.b64encode(out.read_bytes()).decode()


BEFORE = img("before-when.png")
AFTER = img("after-restored.png")

MUTATIONS = [
    (
        "Emit <code>filter</code> instead of <code>declaredMatch(filter, …)</code>",
        "Removes the narrowing entirely — ship every field the form is holding, "
        "whatever the selection declares.",
        "narrows the emitted match to what the selection declares, without losing it",
    ),
    (
        "Drop the <code>resource_ref</code> / <code>resource_type</code> carve-out",
        "Those two are the resource-prefill contract, not connector filter fields. "
        "Narrowing them away breaks prefill from a resource page.",
        "lets connector-wide resource suggestions choose an event",
    ),
    (
        "Restore <code>setFilter(preserveResourceMatch)</code> in <code>toggleEvent</code>",
        "The original bug: wipe the author's filter from state on every toggle "
        "instead of narrowing it on the way out.",
        "narrows the emitted match to what the selection declares, without losing it",
    ),
    (
        "<code>eventKeys.length &gt; 0</code> &rarr; <code>&gt;= 0</code>",
        "Lets an empty selection publish a trigger. <code>event_types</code> is "
        "<code>minItems: 1</code>, so the server would reject it at save.",
        "withholds the trigger when the last event is unchecked",
    ),
    (
        "Drop <code>disabled={slots.length &gt;= MAX_TRIGGERS}</code>",
        "Removes the ceiling, so a 17th trigger card can be filled in before "
        "anything says it is invalid.",
        "stops adding at the contract&rsquo;s ceiling",
    ),
]

rows = "\n".join(
